import { Router } from "express";
import { authmiddle, isRider } from "../middlewares/isAuth.js";
import { acceptorder, addriderprofile, fetchmyorder, fetchmyprofile, toggleavailability, updateorderstatus } from "../controllers/rider.js";
import uploadfile from "../middlewares/multer.js";
const riderroutes = Router();
riderroutes.post('/addrider', authmiddle, isRider, uploadfile, addriderprofile);
riderroutes.get('/get-rider', authmiddle, isRider, fetchmyprofile);
riderroutes.patch('/togglestatus', authmiddle, isRider, toggleavailability);
riderroutes.get('/fetch-order', authmiddle, isRider, fetchmyorder);
riderroutes.post('/accept-order/:orderid', authmiddle, isRider, acceptorder);
riderroutes.put('/update-order/:orderid', authmiddle, isRider, updateorderstatus);
export default riderroutes;
